module app;

fn main() -> Int {
    let ch = std::rt::chan_new();
    var i = 1;
    while i <= 5 {
        let _ = std::rt::chan_send(ch, i * 2);
        i = i + 1;
    }
    let _ = std::rt::chan_close(ch);
    var total = 0;
    var v = std::rt::chan_recv(ch);
    while v >= 0 {
        total = total + v;
        v = std::rt::chan_recv(ch);
    }
    total
}
```

Channels (ADR-0015) carry non-negative Ints by copy through a process-lived Int handle; `chan_recv` returns -1 once the channel is closed AND drained, which is the drain loop's sentinel. An EFFECT, so no spec (R0007).

