```tuo
module example;

spec "std::crypto::scram_client_proof" {
    // The published RFC 7677 section 3 vector needs 4096 PBKDF2 iterations,
    // which exceeds the spec sandbox's instruction-fuel budget — the cost is
    // the point of an iteration count. That vector is therefore pinned by a
    // *native* test instead (`tuo-cli`'s `crypto_cross_check.rs`), and what is
    // checked here is the structure the vector cannot see: that the proof is
    // 32 bytes, that it is `ClientKey XOR ClientSignature` and so recovers the
    // client key when the signature is XORed back out, and that it depends on
    // the auth message.
    then std::array::len(std::crypto::base64_decode(std::string::as_str(
        std::crypto::scram_client_proof(std::crypto::scram_salted_password("pencil", std::crypto::bytes_of_str("salt"), 1), "n=user,r=abc")))) == 32;
    // Different auth messages give different proofs.
    then std::string::as_str(std::crypto::scram_client_proof(std::crypto::scram_salted_password("pencil", std::crypto::bytes_of_str("salt"), 1), "n=user,r=abc"))
        != std::string::as_str(std::crypto::scram_client_proof(std::crypto::scram_salted_password("pencil", std::crypto::bytes_of_str("salt"), 1), "n=user,r=xyz"));
    // A different password gives a different proof.
    then std::string::as_str(std::crypto::scram_client_proof(std::crypto::scram_salted_password("pencil", std::crypto::bytes_of_str("salt"), 1), "n=user,r=abc"))
        != std::string::as_str(std::crypto::scram_client_proof(std::crypto::scram_salted_password("crayon", std::crypto::bytes_of_str("salt"), 1), "n=user,r=abc"));
    // The proof is the XOR of ClientKey and ClientSignature, so XORing the
    // signature back out recovers the key exactly.
    then std::string::as_str(std::crypto::to_hex(std::crypto::xor_bytes(
        std::crypto::base64_decode(std::string::as_str(std::crypto::scram_client_proof(std::crypto::scram_salted_password("pencil", std::crypto::bytes_of_str("salt"), 1), "n=user,r=abc"))),
        std::crypto::hmac_sha256(std::crypto::sha256_bytes(std::string::as_str(std::crypto::str_of_bytes(
            std::crypto::hmac_sha256(std::crypto::scram_salted_password("pencil", std::crypto::bytes_of_str("salt"), 1), std::crypto::bytes_of_str("Client Key"))))),
            std::crypto::bytes_of_str("n=user,r=abc")))))
        == std::string::as_str(std::crypto::to_hex(std::crypto::hmac_sha256(std::crypto::scram_salted_password("pencil", std::crypto::bytes_of_str("salt"), 1), std::crypto::bytes_of_str("Client Key"))));
}
