spec "std::tls::connect" {
    // A failed handshake yields a dead connection — a caller cannot
    // accidentally read or write on one.
    then !std::tls::connect(0, std::tls::failed_handshake()).live;
    // Reading starts in the HANDSHAKE epoch: the client's Finished arrives
    // under its handshake key, not the application key. Starting in the
    // wrong epoch made a real OpenSSL client's Finished fail to
    // authenticate, which is why this is asserted rather than assumed.
    then std::tls::connect(0, std::tls::failed_handshake()).client_epoch_is_handshake;
    then std::tls::connect(0, std::tls::failed_handshake()).read_sequence == 0;
    then std::tls::connect(0, std::tls::failed_handshake()).write_sequence == 0;
    // A failed handshake carries no Finished expectation, and
    // `client_finished_matches` refuses an empty one, so even a connection
    // built from it by mistake could never switch to application keys.
    then std::array::len(std::tls::connect(0, std::tls::failed_handshake()).client_finished) == 0;
}
