spec "std::x25519::field_mod" {
    // Reducing the prime yields zero; a smaller value is unchanged.
    then std::bignum::is_zero(std::x25519::field_mod(std::x25519::prime()));
    then std::bignum::int_or(std::bignum::to_int(std::x25519::field_mod(std::bignum::from_int(7))), 0 - 1) == 7;
    // p + 1 wraps to 1, and p - 1 stays put: the two sides of the boundary
    // the final conditional subtraction has to get right.
    then std::bignum::int_or(
        std::bignum::to_int(std::x25519::field_mod(std::bignum::add(std::x25519::prime(), std::bignum::from_int(1)))),
        0 - 1,
    ) == 1;
    then std::bignum::compare(
        std::x25519::field_mod(std::bignum::sub(std::x25519::prime(), std::bignum::from_int(1))),
        std::bignum::sub(std::x25519::prime(), std::bignum::from_int(1)),
    ) == 0;
    // 2^255 reduces to 19 — the identity the whole fast reduction is built
    // on. If this were wrong, every field operation would be.
    then std::bignum::int_or(
        std::bignum::to_int(std::x25519::field_mod(std::bignum::shift_left(std::bignum::from_int(1), 255))),
        0 - 1,
    ) == 19;
    // 2^256 reduces to 38 = 2 * 19, checking the fold scales.
    then std::bignum::int_or(
        std::bignum::to_int(std::x25519::field_mod(std::bignum::shift_left(std::bignum::from_int(1), 256))),
        0 - 1,
    ) == 38;
    // Every result is a genuine field element.
    then std::bignum::compare(std::x25519::field_mod(std::bignum::shift_left(std::bignum::from_int(1), 400)), std::x25519::prime())
        < 0;
}
