    then std::array::len(row_columns(std::string::as_str(data_row("42")))) == 1;
    then std::string::as_str(std::array::get(row_columns(std::string::as_str(data_row("42"))), 0)) == "42";
    // A longer value survives intact.
    then std::string::as_str(std::array::get(row_columns(std::string::as_str(data_row("hello"))), 0)) == "hello";
