/// A one-field `RowDescription` payload naming `name` with type `oid`. Spec
/// helper for [`row_description_oids`], which parses what a server sends.
///
/// ```tuo
/// std::array::len(postgres_client::row_description_oids(std::string::as_str(postgres_client::described("n", 23))))  // 1
/// ```
pub fn described(in name: Str, take oid: Int) -> String {
    var out = std::string::empty();
    // One field.
    std::string::push_byte(out, 0);
    std::string::push_byte(out, 1);
    push_cstring(out, name);
    // Table OID and column number precede the type OID.
    push_be32(out, 0);
    std::string::push_byte(out, 0);
    std::string::push_byte(out, 1);
    push_be32(out, oid);
    // Type size, modifier, and format code follow it.
    std::string::push_byte(out, 0);
    std::string::push_byte(out, 4);
    push_be32(out, 0 - 1);
    std::string::push_byte(out, 0);
    std::string::push_byte(out, 0);
    out
}

spec described {
    // Two bytes of count, the name and its terminator, then 18 fixed bytes.
    then std::string::len(described("n", 23)) == 22;
    then std::string::byte_at(described("n", 23), 1) == 1;
}
